"""Scoped observability state for voice calls.

A :class:`CallObservabilityContext` stores correlation identifiers, audio
totals, and the active turn for one voice call. The turn state itself is the
channel-neutral :class:`~rasa.tracing.turn.context.TurnObservabilityContext`;
this module registers the resolver that routes the neutral turn accessor
through the active call, and hosts the voice-side adapters around it.
"""

from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
from typing import TYPE_CHECKING, Any, Dict, Iterator, Optional

from opentelemetry.trace import Span
from pydantic import BaseModel

from rasa.tracing.turn.attribute_values import TurnOutputModality, TurnTriggerType
from rasa.tracing.turn.context import (
    TurnInputAnchor,
    TurnObservabilityContext,
    get_current_turn_observability_context,
    set_active_turn_resolver,
)
from rasa.tracing.voice.shared import semconv

if TYPE_CHECKING:
    from rasa.core.voice.event_composition.events import CompositeEvent


# ---------------------------------------------------------------------------
# State model
# ---------------------------------------------------------------------------


class CallObservabilityContext(BaseModel):
    """Correlation ids and observability state accumulated over one voice call.

    Audio counters and turn state are mutable for the duration of the call.
    """

    call_id: Optional[str] = None
    conversation_id: Optional[str] = None

    audio_input_bytes_total: int = 0
    audio_input_chunk_count: int = 0
    audio_output_bytes_total: int = 0
    audio_output_chunk_count: int = 0

    turn_count: int = 0
    current_turn: Optional[TurnObservabilityContext] = None

    def get_span_correlation_attributes(self) -> Dict[str, Any]:
        """Return call/session identifiers formatted as span attributes."""
        attributes: Dict[str, Any] = {}
        if self.conversation_id:
            attributes[semconv.RASA_CONVERSATION_ID] = self.conversation_id
        if self.call_id:
            attributes[semconv.VOICE_CHANNEL_CALL_ID] = self.call_id
        return attributes

    def record_input_audio(self, num_bytes: int) -> None:
        """Count one incoming audio chunk of ``num_bytes`` bytes."""
        self.audio_input_bytes_total += num_bytes
        self.audio_input_chunk_count += 1

    def record_output_audio(self, num_bytes: int) -> None:
        """Count one outgoing audio chunk of ``num_bytes`` bytes."""
        self.audio_output_bytes_total += num_bytes
        self.audio_output_chunk_count += 1

    def begin_turn(
        self, anchor: Optional[TurnInputAnchor] = None
    ) -> TurnObservabilityContext:
        """Open observability state for the turn starting now (1-based index).

        Args:
            anchor: The turn's input anchor, when known, so the turn measures
                latency from the user's input. Voice turns answer in audio.
        """
        self.turn_count += 1
        self.current_turn = TurnObservabilityContext.from_input_anchor(
            anchor,
            index=self.turn_count,
            output_modality=TurnOutputModality.AUDIO,
        )
        return self.current_turn

    def end_turn(self) -> None:
        """Clear the active turn's observability state."""
        self.current_turn = None

    def stamp_root_span(self, span: Span) -> None:
        """Write the accumulated totals onto the (closing) root call span."""
        span.set_attribute(
            semconv.AUDIO_INPUT_BYTES_TOTAL, self.audio_input_bytes_total
        )
        span.set_attribute(
            semconv.AUDIO_INPUT_CHUNK_COUNT, self.audio_input_chunk_count
        )
        span.set_attribute(
            semconv.AUDIO_OUTPUT_BYTES_TOTAL, self.audio_output_bytes_total
        )
        span.set_attribute(
            semconv.AUDIO_OUTPUT_CHUNK_COUNT, self.audio_output_chunk_count
        )


# ---------------------------------------------------------------------------
# Context binding
# ---------------------------------------------------------------------------


_call_observability: ContextVar[Optional[CallObservabilityContext]] = ContextVar(
    "rasa_voice_call_observability", default=None
)


@contextmanager
def call_observability_context(
    call_id: str, conversation_id: str
) -> Iterator[CallObservabilityContext]:
    """Bind a fresh observability context for the duration of one call."""
    observability = CallObservabilityContext(
        call_id=call_id, conversation_id=conversation_id
    )
    token = _call_observability.set(observability)
    try:
        yield observability
    finally:
        _call_observability.reset(token)


# ---------------------------------------------------------------------------
# Accessors
# ---------------------------------------------------------------------------


def get_current_call_observability_context() -> Optional[CallObservabilityContext]:
    """Return the active call's observability context, or ``None``.

    ``None`` outside an active voice call — including whenever voice
    observability (tracing and metrics) is disabled, since no context is
    bound then.
    """
    return _call_observability.get()


def _resolve_call_bound_turn() -> Optional[TurnObservabilityContext]:
    """Return the active call's current turn, if any.

    Registered as the neutral turn resolver so channel tasks — which inherit
    only the call binding, not the turn binding — still reach the turn state.
    """
    observability = _call_observability.get()
    if observability is None:
        return None
    return observability.current_turn


set_active_turn_resolver(_resolve_call_bound_turn)


# ---------------------------------------------------------------------------
# Voice adapters around the channel-neutral turn state
# ---------------------------------------------------------------------------


def turn_input_anchor_from_event(
    event: "CompositeEvent",
) -> Optional[TurnInputAnchor]:
    """Build an input anchor for a voice user-turn event, if applicable."""
    # Import here to avoid a cycle between voice events and tracing.
    from rasa.core.voice.event_composition.events import (
        SilenceTimeoutInteractionEvent,
        UserDTMFInput,
        UserTranscript,
    )

    input_types: Dict[type, TurnTriggerType] = {
        UserTranscript: TurnTriggerType.SPEECH,
        UserDTMFInput: TurnTriggerType.DTMF,
        SilenceTimeoutInteractionEvent: TurnTriggerType.SILENCE_TIMEOUT,
    }
    input_type = input_types.get(type(event))
    if input_type is None:
        return None
    return TurnInputAnchor(
        input_type=input_type,
        triggered_at_monotonic=event.turn_triggered_at_monotonic,
    )


# ---------------------------------------------------------------------------
# Recording helpers
# ---------------------------------------------------------------------------


def record_call_input_audio(num_bytes: int) -> None:
    """Count one incoming audio chunk on the active call, if any."""
    if (observability := get_current_call_observability_context()) is not None:
        observability.record_input_audio(num_bytes)


def record_call_output_audio(num_bytes: int) -> None:
    """Count one outgoing audio chunk on the active call, if any."""
    if (observability := get_current_call_observability_context()) is not None:
        observability.record_output_audio(num_bytes)


def record_turn_tts_first_byte() -> None:
    """Record the first TTS audio sent during the active turn.

    Later utterances do not move this anchor. Their per-message TTS latency
    is tracked by ``SynthesizeSpeechRecorder``.
    """
    if (turn := get_current_turn_observability_context()) is not None:
        turn.record_first_audio_output()
